import org.junit.jupiter.api.Test;

class ChangesetByteEstimateTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI SUBJECT = VF.createIRI("urn:changeset-size:subject");
	private static final IRI PREDICATE = VF.createIRI("urn:changeset-size:predicate");

	@Test
	void deepTermsAreEstimatedBeforeModelInsertionWithoutRecursion() {
		Value value = VF.createLiteral("leaf");
		for (int i = 0; i < 16384; i++) {
			value = new Term(value);
		}
		// Isolate advisory estimation from the model's separately specified statement hashing.
		Statement statement = statement(value);
		try (TrackingChangeset changeset = new TrackingChangeset()) {
			assertDoesNotThrow(() -> changeset.approve(statement));
			assertTrue(changeset.getApproximateWriteIntentBytes() >= 16384L * 64L);
			assertTrue(changeset.getApproximateWriteIntentBytes() < 16384L * 1024L);
			assertTrue(changeset.signals > 0);
		}
	}

	@Test
	void cyclicTermsAreRejectedBeforeModelInsertion() {
		Term self = new Term(null);
		self.object = self;
		Term first = new Term(null);
		Term second = new Term(first);
		first.object = second;
		Value prefixed = first;
		for (int i = 0; i < 127; i++) {
			prefixed = new Term(prefixed);
		}
		Statement prefixedStatement = statement(prefixed);
		try (TrackingChangeset changeset = new TrackingChangeset()) {
			assertThrows(IllegalArgumentException.class, () -> changeset.approve(statement(self)));
			assertThrows(IllegalArgumentException.class, () -> changeset.deprecate(statement(first)));
			assertThrows(IllegalArgumentException.class, () -> changeset.approve(prefixedStatement));
		}
	}

	private static Statement statement(Value object) {
		Statement statement = mock(Statement.class);
		when(statement.getSubject()).thenReturn(SUBJECT);
		when(statement.getPredicate()).thenReturn(PREDICATE);
		when(statement.getObject()).thenReturn(object);
		return statement;
	}

	private static final class TrackingChangeset extends Changeset {
		private int signals;

		@Override
		protected boolean tracksWriteIntent() {
			return true;
		}

		@Override
		protected void writeIntentChanged() {
			signals++;
		}

		@Override
		public void flush() {
		}

		@Override
		public Model createEmptyModel() {
			return new DynamicModelFactory().createEmptyModel();
		}
	}

	private static final class Term extends AbstractTripleTerm {
		private Value object;

		private Term(Value object) {
			this.object = object;
		}

		@Override
		public Resource getSubject() {
			return SUBJECT;
		}

		@Override
		public IRI getPredicate() {
			return PREDICATE;
		}

		@Override
		public Value getObject() {
			return object;
		}
	}
}
